CREATE TABLE [dbo].[RouteTemplate] (
    [RouteTemplateID] INT IDENTITY (1, 1) NOT NULL,
    [InActive] BIT CONSTRAINT [DF_RouteTemplate_InActive] DEFAULT ((0)),
    CONSTRAINT [PK_RouteTemplate] PRIMARY KEY CLUSTERED ([RouteTemplateID] ASC)
    WITH (PAD_INDEX = OFF, STATISTICS_NORECOMPUTE = OFF, ALLOW_PAGE_LOCKS = ON) ON [PRIMARY]
) ON [PRIMARY];

CREATE TABLE t (
    a INT,
    CONSTRAINT UQ_a UNIQUE NONCLUSTERED (a) WITH (PAD_INDEX = OFF),
    CONSTRAINT CK_a CHECK (a > 0)
);
